package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for overly broad permissions in access control
    broad_permission_patterns := {"Action", "Resource", "role", "roles", "permissions", "policy"}
    broad_permission_values := {"*", ".*", ".*:.*"}

    attr.name == broad_permission_patterns[_]
    check_broad_permission(attr.value, broad_permission_values)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly broad permissions detected in access control. Violates least privilege principle. (CWE-250)"
    }
}

