    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for admin role assignments to non-admin entities
    admin_role_patterns := {"Owner", "FullAccess", "Administrator", "Admin", "Root", "SuperUser"}
    non_admin_entities := {"user", "service", "group", "role", "account"}

    attr.name in non_admin_entities
    check_admin_role(attr.value, admin_role_patterns)

